/// e.g., "mise.test.toml" -> Some("test"), "mise.test.local.toml" -> Some("test"), "mise.toml" -> None
pub(crate) fn extract_env_from_config_path(path: &Path) -> Option<String> {
    let filename = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default();

    // Pattern matches:
    // - mise.{env}.toml -> captures env
    // - mise.{env}.local.toml -> captures env (env-specific local config)
    // - .mise.{env}.toml -> captures env
    // - config.{env}.toml -> captures env
    // Does NOT match (returns None):
    // - mise.toml, .mise.toml, config.toml (base configs)
    // - mise.local.toml (local without env - filtered by "local" check)
    let re = regex!(r"^(?:\.?mise|config)\.([^.]+)(?:\.local)?\.toml$");
    re.captures(filename)
        .and_then(|caps| caps.get(1))
        .map(|m| m.as_str().to_string())
        .filter(|s| s != "local")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum LockfileUpdateMode {
    Normal,
    AllowLocked,
}

impl LockfileUpdateMode {
    fn allow_locked(self) -> bool {
        matches!(self, Self::AllowLocked)
    }
}

pub(crate) fn migrate_monorepo_lockfiles(
    config: &Config,
    allow_format_upgrade: bool,
) -> Result<()> {
    migrate_monorepo_lockfiles_inner(config, allow_format_upgrade, true, None)
}

pub(crate) fn monorepo_lockfile_migration_paths(config: &Config) -> Vec<(PathBuf, PathBuf)> {
    let Some(monorepo_root) = config.monorepo_lockfile_root() else {
        return Vec::new();
    };
    monorepo_legacy_lockfile_paths(config)
        .into_iter()
        .filter_map(|source| {
            let filename = source.file_name()?;
            let target = monorepo_root.join(filename);
            (source != target).then_some((source, target))
        })
        .collect()
}

pub(crate) fn migrate_monorepo_lockfiles_already_locked(
    config: &Config,
    allow_format_upgrade: bool,
    migration_paths: &[(PathBuf, PathBuf)],
) -> Result<()> {
    migrate_monorepo_lockfiles_inner(config, allow_format_upgrade, false, Some(migration_paths))
}

fn migrate_monorepo_lockfiles_inner(
    config: &Config,
    allow_format_upgrade: bool,
    acquire_target_locks: bool,
    migration_paths: Option<&[(PathBuf, PathBuf)]>,
) -> Result<()> {
    if !Settings::get().lockfile_enabled() {
        return Ok(());
    }
    let Some(monorepo_root) = config.monorepo_lockfile_root() else {
        return Ok(());
    };
    let mut migrated = 0usize;

    let discovered_paths;
    let migration_paths = match migration_paths {
        Some(paths) => paths,
        None => {
            discovered_paths = monorepo_lockfile_migration_paths(config);
            &discovered_paths
        }
    };
    for (source, target) in migration_paths {
        if !source.exists() {
            continue;
        }
        let _lock = acquire_target_locks
            .then(|| {
                crate::lock_file::LockFile::new(target)
                    .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
                    .lock()
            })
            .transpose()?;
        let target_existed = target.exists();
        let mut root_lockfile =
            Lockfile::read(target).unwrap_or_else(|err| handle_lockfile_read_error(err, target));
        let subproject_lockfile = match Lockfile::read(source) {
            Ok(lockfile) => lockfile,
            Err(err) if is_not_found_report(&err) => continue,
            Err(err) => return Err(err),
        };
        if !target_existed {
            root_lockfile.lockfile_version = subproject_lockfile.lockfile_version;
        } else if root_lockfile.lockfile_version != subproject_lockfile.lockfile_version
            && allow_format_upgrade
        {
            // Keep the newer format so request bindings from either input remain
            // serialized if the subsequent rebuild fails. Entries imported from
            // version 0 remain reachable through the unbound-entry fallback.
            root_lockfile.lockfile_version = root_lockfile
                .lockfile_version
                .max(subproject_lockfile.lockfile_version);
        } else if root_lockfile.lockfile_version != subproject_lockfile.lockfile_version {
            bail!(
                "cannot merge lockfile version {} from {} into lockfile version {} at {}; run `mise lock --upgrade` at the monorepo root",
                subproject_lockfile.lockfile_version,
                display_path(source),
                root_lockfile.lockfile_version,
                display_path(target)
            );
        }
        merge_lockfile_preserving_root(&mut root_lockfile, subproject_lockfile);
        root_lockfile.save(target)?;
        if let Err(err) = fs::remove_file(source)
            && err.kind() != ErrorKind::NotFound
        {
            return Err(err.into());
        }
        migrated += 1;
    }

    if migrated > 0 {
        miseprintln!(
            "migrated {migrated} subproject lockfile(s) into {} (monorepo uses a single root lockfile)",
            display_path(&monorepo_root)
        );
    }

    Ok(())
}

fn is_not_found_report(err: &Report) -> bool {
    err.downcast_ref::<std::io::Error>()
        .is_some_and(|err| err.kind() == ErrorKind::NotFound)
}

fn monorepo_legacy_lockfile_paths(config: &Config) -> IndexSet<PathBuf> {
    let Some(cache_key) = config.monorepo_lockfile_discovery_key() else {
        return IndexSet::new();
    };
    cached_legacy_lockfile_paths(cache_key, || {
        discover_monorepo_legacy_lockfile_paths(config)
    })
}

fn cached_legacy_lockfile_paths(
    cache_key: LegacyLockfilePathsCacheKey,
    discover: impl FnOnce() -> IndexSet<PathBuf>,
) -> IndexSet<PathBuf> {
    let mut cache = LEGACY_LOCKFILE_PATHS_CACHE
        .lock()
        .unwrap_or_else(|err| err.into_inner());
    if let Some(paths) = cache.get(&cache_key) {
        return paths.clone();
    }
    let paths = discover();
    cache.insert(cache_key, paths.clone());
    paths
}

fn discover_monorepo_legacy_lockfile_paths(config: &Config) -> IndexSet<PathBuf> {
    let Some(monorepo_root) = config.monorepo_lockfile_root() else {
        return IndexSet::new();
    };
    let config_roots = match config.monorepo_config_root_dirs_for_lockfiles() {
        Ok(config_roots) => config_roots,
        Err(err) => {
            warn_once!(
                "[monorepo] lockfile = true is set, but [monorepo].config_roots could not be resolved: {err:#}; using root lockfiles without migration"
            );
            return IndexSet::new();
        }
    };
    let mut source_lockfiles = IndexSet::new();

    for config_root in config_roots {
        if config_root == monorepo_root {
            continue;
        }
        for source in lockfile_variant_paths_in_dir(&config_root) {
            if source.parent() != Some(monorepo_root.as_path()) {
                source_lockfiles.insert(source);
            }
        }
        for config_path in crate::config::config_paths_in_dir(&config_root) {
            if let Some(source) = legacy_lockfile_path_for_config(&config_path, &monorepo_root) {
                source_lockfiles.insert(source);
            }
        }
    }

    source_lockfiles
}

pub(crate) fn lockfile_variant_paths_in_dir(dir: &Path) -> Vec<PathBuf> {
    let mut paths = IndexSet::new();

    for path in crate::config::glob(dir, "mise*.lock").unwrap_or_default() {
        paths.insert(path);
    }
    for env_name in env::MISE_ENV.iter().chain(env::AUTO_ENV_NAMES.iter()) {
        paths.insert(dir.join(format!("mise.{env_name}.local.lock")));
        paths.insert(dir.join(format!("mise.{env_name}.lock")));
    }
    paths.insert(dir.join("mise.local.lock"));
    paths.insert(dir.join("mise.lock"));

    paths.into_iter().collect()
}

fn legacy_lockfile_path_for_config(config_path: &Path, monorepo_root: &Path) -> Option<PathBuf> {
    if !config_path.starts_with(monorepo_root) {
        return None;
    }
    let (source, _) = lockfile_path_for_config(config_path, None);
    (source.parent() != Some(monorepo_root)).then_some(source)
}

fn merge_legacy_lockfile_if_present(
    lockfile: &mut Lockfile,
    legacy_path: &Path,
    primary_exists: bool,
) -> Result<()> {
    match Lockfile::read(legacy_path) {
        Ok(legacy) => {
            if primary_exists {
                merge_lockfile_for_lookup(lockfile, legacy);
            } else {
                *lockfile = legacy;
            }
            Ok(())
        }
        Err(err) if is_not_found_report(&err) => Ok(()),
        Err(err) => Err(err),
    }
}

fn merge_lockfile_for_lookup(root: &mut Lockfile, other: Lockfile) {
    // A mixed-format read must keep request bindings enabled. Version-0 entries
    // have no specifiers and remain available through the versioned lockfile's
    // unbound-entry fallback.
    root.lockfile_version = root.lockfile_version.max(other.lockfile_version);
    merge_lockfile_preserving_root(root, other);
}

fn merge_lockfile_preserving_root(root: &mut Lockfile, other: Lockfile) {
    for (short, tools) in other.tools {
        let root_tools = root.tools.entry(short).or_default();
        let mut keys: HashSet<(String, BTreeMap<String, String>)> = root_tools
            .iter()
            .map(|tool| (tool.version.clone(), tool.options.clone()))
            .collect();
        for tool in tools {
            let key = (tool.version.clone(), tool.options.clone());
            if let Some(existing) = root_tools.iter_mut().find(|existing| {
                existing.version == tool.version && existing.options == tool.options
            }) {
                existing.specifiers.extend(tool.specifiers);
            } else if keys.insert(key) {
                root_tools.push(tool);
            }
        }
    }

    for (platform, packages) in other.conda_packages {
        let root_packages = root.conda_packages.entry(platform).or_default();
        for (basename, info) in packages {
            root_packages.entry(basename).or_insert(info);
        }
    }

    for (platform, packages) in other.pkgx_packages {
        let root_packages = root.pkgx_packages.entry(platform).or_default();
        for (id, info) in packages {
            root_packages.entry(id).or_insert(info);
        }
    }
}

/// Groups the resolved toolset plus this session's newly installed versions by
/// the config source that requested each of them.
///
/// Each new version must be attributed to its own request's source: one
/// command can install versions of the same backend requested by different
/// config files, and grouping them by backend attributed the whole group to
/// the first request's source, writing entries into the wrong lockfile.
fn tools_by_source_for_update(
    ts: &Toolset,
    new_versions: &[ToolVersion],
) -> HashMap<ToolSource, HashMap<String, Vec<ToolVersion>>> {
    // Collect tools by source (config file)
    let mut tools_by_source: HashMap<ToolSource, HashMap<String, Vec<ToolVersion>>> =
        HashMap::new();
    for (ba, tvl) in &ts.versions {
        for tv in &tvl.versions {
            tools_by_source
                .entry(tv.request.source().clone())
                .or_default()
                .entry(ba.short.to_string())
                .or_default()
                .push(tv.clone());
        }
    }

    // Add versions added within this session (from `mise use` or `mise up`),
    // replacing the resolved entry for the same request within that source.
    for new_tv in new_versions {
        let existing_versions = tools_by_source
            .entry(new_tv.request.source().clone())
            .or_default()
            .entry(new_tv.ba().short.to_string())
            .or_default();
        existing_versions.retain(|tv| tv.request.version() != new_tv.request.version());
        existing_versions.push(new_tv.clone());
    }

    tools_by_source
}

