                    conda_deps: platform_info.conda_deps,
                    pkgx_deps: platform_info.pkgx_deps,
                    pkgx_provides: platform_info.pkgx_provides,
                    pkgx_runtime_env: platform_info.pkgx_runtime_env,
                    provenance,
                    provenance_verified,
                    github_attestations: None,
                    attested_by: if platform_info.signer.is_some() {
                        platform_info.attested_by
                    } else {
                        existing.attested_by.clone()
                    },
                    signer: platform_info.signer.or_else(|| existing.signer.clone()),
                    additional_artifacts: if preserve_artifact_fields {
                        merge_additional_artifacts(
                            &platform_info.additional_artifacts,
                            &existing.additional_artifacts,
                        )
                    } else {
                        platform_info.additional_artifacts
                    },
                }
            } else {
                platform_info
            };
            // Only insert non-empty platform info to avoid `"platforms.linux-x64" = {}`
            if !merged.is_empty() {
                tool.platforms.insert(platform_key.to_string(), merged);
            }
        } else {
            let mut platforms = BTreeMap::new();
            // Only insert non-empty platform info
            if !platform_info.is_empty() {
                platforms.insert(platform_key.to_string(), platform_info);
            }
            tools.push(LockfileTool {
                version: version.to_string(),
                backend: backend.map(|s| s.to_string()),
                specifiers: BTreeSet::new(),
                options: options.clone(),
                platforms,
            });
        }

        // Do not remove this platform from sibling option variants. A monorepo
        // root lockfile can legitimately contain the same version and platform
        // for multiple requests with different options. Legacy migration is
        // handled by the consensus-based merge pass, where all contributing
        // requests are available.
    }

    /// Save the lockfile to disk (public for mise lock command)
    pub(crate) fn write<P: AsRef<Path>>(&self, path: P) -> Result<()> {
        self.save(path)
    }
}

/// Determines the lockfile path for a given config file path
/// Returns (lockfile_path, is_local)
///
/// Lockfiles are placed alongside their config files:
/// - `mise.toml` -> `mise.lock`
/// - `.config/mise.toml` -> `.config/mise.lock`
/// - `.mise/config.toml` -> `.mise/mise.lock`
/// - `.mise/conf.d/foo.toml` -> `.mise/mise.lock` (conf.d files share parent's lockfile)
/// - `mise/conf.d/foo.toml` -> `mise/mise.lock`
pub(crate) fn lockfile_path_for_config(
    config_path: &Path,
    monorepo_root: Option<&Path>,
) -> (PathBuf, bool) {
    let is_local = is_local_config(config_path);
    let env = extract_env_from_config_path(config_path);
    let lockfile_name = match (&env, is_local) {
        (Some(e), true) => format!("mise.{e}.local.lock"),
        (Some(e), false) => format!("mise.{e}.lock"),
        (None, true) => "mise.local.lock".to_string(),
        (None, false) => "mise.lock".to_string(),
    };

    let parent = config_path.parent().unwrap_or(Path::new("."));
    let parent_name = parent
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default();

    // For conf.d files, place lockfile at parent of conf.d so all conf.d files share one lockfile
    let lockfile_dir = if parent_name == "conf.d" {
        parent.parent().unwrap_or(parent)
    } else {
        parent
    };

    let lockfile_dir = if let Some(root) = monorepo_root
        && config_path.starts_with(root)
        && lockfile_dir != root
    {
        root
    } else {
        lockfile_dir
    };

    (lockfile_dir.join(lockfile_name), is_local)
}

/// Determines the lockfile path for a tool source.
///
/// Idiomatic version files are not config files themselves, so their lock entries
/// belong to the nearest active mise config root that contains the version file.
/// If multiple base configs share that root, the later entry in config_files wins
/// so colocated configs have a deterministic lockfile target, such as
/// .mise/config.toml mapping .dummy-version to .mise/mise.lock instead of mise.lock.
pub(crate) fn lockfile_path_for_tool_source(
            .any(|tool| tool.version == baseline.version && tool.options == baseline.options)
        {
            merged_tools.push(baseline.clone());
        }
    }
}

/// Drop prior-version entries that survived the merge only as deferred provenance
/// baselines once the upgrade they guarded has cryptographically verified provenance
/// on `platform_key`.
///
/// `reinsert_deferred_baselines` keeps the prior provenance-bearing version alive when
/// an already-installed upgrade skipped its download, so the auto-lock pass can compare
/// the two. Once that pass records provenance for the new version the baseline has done
/// its job; leaving it behind ships a lockfile listing two versions of the tool until
/// some later command rewrites it. Only entries no request still resolves to are
/// removed, and only when they are exactly the baseline the verified version would have
/// been checked against. Detection-only provenance (for example an entry another
/// platform's `mise lock` populated for this one) does not count, and a baseline that
/// another requested entry (say a second option variant of the same version) is still
/// waiting on stays until that entry verifies too. Returns the pruned versions.
fn prune_verified_provenance_baselines(
    tools: &mut Vec<LockfileTool>,
    requested_versions: &BTreeSet<String>,
    platform_key: &str,
) -> Vec<String> {
    let mut pruned = Vec::new();
    loop {
        let verified_here = |tool: &LockfileTool| {
            tool.platforms
                .get(platform_key)
                .is_some_and(|info| info.provenance.is_some() && info.provenance_verified)
        };
        // The baseline the deferred regression check for `tool` compares against, as
        // `check_provenance_regression` computes it for a not-yet-verified entry.
        let baseline_of = |tool: &LockfileTool| {
            find_provenance_regression_baseline(
                Some(tools.as_slice()),
                &tool.version,
                tool.backend.as_deref().unwrap_or(""),
                platform_key,
                None,
            )
            .map(|baseline| (baseline.version.clone(), baseline.options.clone()))
        };
        let requested = tools
            .iter()
            .filter(|tool| requested_versions.contains(&tool.version));
        let still_needed: HashSet<LockfileToolKey> = requested
            .clone()
            .filter(|tool| !verified_here(tool))
            .filter_map(baseline_of)
            .collect();
        let stale = requested
            .filter(|tool| verified_here(tool))
            .filter_map(baseline_of)
            .find(|key| !requested_versions.contains(&key.0) && !still_needed.contains(key));
        let Some((version, options)) = stale else {
            return pruned;
        };
        tools.retain(|tool| tool.version != version || tool.options != options);
        pruned.push(version);
    }
}

/// Check if any github backend tool is losing provenance when upgrading versions.
///
/// Only checks the current platform because new `LockfileTool` entries (from
/// `ToolVersionList`) only have `lock_platforms` populated for the platform where
/// installation ran. Checking other platforms would produce false positives.
///
/// A regression is only *confirmed* when the new version was actually downloaded and
/// resolved this session — signalled by a `url` on the current platform. When a user
/// "upgrades" to a version that is *already installed* on disk, mise skips the download
/// entirely, so no provenance is populated and the platform entry has no url. Its
/// missing provenance means "not checked", not "verified absent" — flagging it as a
/// regression is a false positive (#11225). For those, the prior provenance-bearing
/// entry is instead preserved as a baseline so the authoritative `auto_lock_new_versions`
/// pass can download, verify, and compare against it.
fn check_provenance_regression(
    existing_lockfile: &Lockfile,
    new_tools: &HashMap<String, Vec<LockfileTool>>,
) -> ProvenanceRegressionCheck {
    let current_platform = Platform::current().to_key();
    let mut result = ProvenanceRegressionCheck::default();

    for (short, new_entries) in new_tools {
        for new_entry in new_entries {
            let backend = new_entry.backend.as_deref().unwrap_or("");
            let platform_info = new_entry.platforms.get(&current_platform);
            let new_provenance = platform_info.and_then(|pi| pi.provenance.as_ref());

            let Some(baseline) = find_provenance_regression_baseline(
                existing_lockfile.tools.get(short).map(Vec::as_slice),
                &new_entry.version,
                backend,
                &current_platform,
                new_provenance,
            ) else {
                continue;
            };

            if platform_info.and_then(|pi| pi.url.as_ref()).is_some() {
                // Freshly downloaded and verified: the new version genuinely lacks
                // provenance the prior version had — a confirmed regression.
                result.regressing.insert(short.clone());
                result.errors.push(provenance_regression_message(
                    short,
                    &new_entry.version,
                    &current_platform,
                    baseline,
                ));
            } else {
                // Not downloaded this session (already installed on disk): unverified.
                // Preserve the baseline so auto-lock can make the authoritative call.
                result
                    .deferred_baselines
                    .entry(short.clone())
                    .or_default()
                    .push(baseline.clone());
            }
        }
    }
    result
}

/// Snapshot the platform keys present in each lockfile that the upcoming install run
/// will touch. Must be called BEFORE `update_lockfiles` writes any current-platform
/// entries — the snapshot is what lets `auto_lock_new_versions` tell a user-curated
/// lockfile (existing entries are authoritative) apart from a fresh one whose only
/// current-platform entry was just added by this install.
pub(crate) fn snapshot_pre_install_platforms(
    config: &Config,
    ts: &Toolset,
    new_versions: &[ToolVersion],
) -> HashMap<PathBuf, BTreeSet<String>> {
    let mut result: HashMap<PathBuf, BTreeSet<String>> = HashMap::new();
    for tv in ts
        .versions
        .values()
        .flat_map(|tvl| tvl.versions.iter())
        .chain(new_versions.iter())
    {
        let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, tv.request.source())
        else {
            continue;
        };
        if result.contains_key(&lockfile_path) {
            continue;
        }
        let keys = if lockfile_path.exists() {
            Lockfile::read(&lockfile_path)
                .map(|lf| lf.all_platform_keys())
                .unwrap_or_default()
        } else {
            BTreeSet::new()
        };
        result.insert(lockfile_path, keys);
    }
    result
}

fn tool_version_matches_lockfile_target<F>(
    lockfile: &Lockfile,
    tv: &ToolVersion,
    target_platforms: &[Platform],
    predicate: F,
) -> Result<bool>
where
    F: Fn(&[LockfileTool], &str, &str, &BTreeMap<String, String>) -> bool,
{
    let Some(tools) = lockfile.tools.get(tv.short()) else {
        return Ok(false);
    };
    // The toolset passed to auto-locking can still contain the version that was
    // active before an upgrade. If that version has already been pruned from the
    // lockfile, it is stale and must not be resolved back into the file.
    if !tools.iter().any(|tool| tool.version == tv.version) {
        return Ok(false);
    }
    let backend = tv.request.backend()?;

    for platform in target_platforms {
        for variant in backend.platform_variants(platform) {
            let target = PlatformTarget::new(variant.clone());
            let options = backend.resolve_lockfile_options(&tv.request, &target)?;
            let platform_key = variant.to_key();
            if predicate(tools, &tv.version, &platform_key, &options) {
                return Ok(true);
            }
        }
    }

    Ok(false)
}

fn tool_version_needs_auto_lock(
    lockfile: &Lockfile,
    tv: &ToolVersion,
    target_platforms: &[Platform],
) -> Result<bool> {
    tool_version_matches_lockfile_target(
        lockfile,
        tv,
        target_platforms,
        lockfile_target_needs_auto_lock,
    )
}

fn lockfile_target_needs_auto_lock(
    tools: &[LockfileTool],
    version: &str,
    platform_key: &str,
    options: &BTreeMap<String, String>,
) -> bool {
    let Some(tool) = tools
        .iter()
        .find(|tool| tool.version == version && &tool.options == options)
    else {
        return true;
    };
    let Some(info) = tool.platforms.get(platform_key) else {
        return true;
    };
    if info.checksum.is_none() || info.url.is_none() {
        return true;
    }

    // A complete-looking same-version row can still be an unresolved deferred
    // provenance upgrade. Force resolution while a verified prior baseline exists.
    find_provenance_regression_baseline(
        Some(tools),
        version,
        tool.backend.as_deref().unwrap_or(""),
        platform_key,
        info.provenance.as_ref(),
    )
    .is_some()
}

fn lockfile_target_has_deferred_provenance(
    tools: &[LockfileTool],
    version: &str,
    platform_key: &str,
    options: &BTreeMap<String, String>,
) -> bool {
    let Some(tool) = tools
        .iter()
        .find(|tool| tool.version == version && &tool.options == options)
    else {
        return false;
    };
    let provenance = tool
        .platforms
        .get(platform_key)
        .and_then(|info| info.provenance.as_ref());
    find_provenance_regression_baseline(
        Some(tools),
        version,
        tool.backend.as_deref().unwrap_or(""),
        platform_key,
        provenance,
    )
    .is_some()
}

fn tool_version_needs_deferred_provenance_retry(
    lockfile: &Lockfile,
    tv: &ToolVersion,
    target_platforms: &[Platform],
) -> Result<bool> {
    tool_version_matches_lockfile_target(
        lockfile,
        tv,
        target_platforms,
        lockfile_target_has_deferred_provenance,
    )
}

/// Determine target platforms for auto-lock from the pre-install lockfile snapshot.
///
/// If the lockfile had platform entries before this install run, those are authoritative
/// (plus the current platform). Otherwise — the lockfile was fresh — fall back to the
/// common platform set so a brand-new lockfile gets cross-platform-populated. The
/// `lockfile_platforms` setting overrides both paths.
fn determine_target_platforms_from_lockfile(
    pre_install_keys: &BTreeSet<String>,
) -> Result<Vec<Platform>> {
    if let Some(configured) = Settings::get().lockfile_platforms()? {
        let mut platforms: BTreeSet<Platform> = configured.into_iter().collect();
        platforms.insert(Platform::current());
        return Ok(platforms.into_iter().collect());
    }

    if !pre_install_keys.is_empty() {
        let mut platforms: BTreeSet<Platform> = BTreeSet::new();
        for platform_key in pre_install_keys {
            if let Ok(p) = Platform::parse(platform_key)
                && p.validate().is_ok()
            {
                platforms.insert(p);
            }
        }
        if !platforms.is_empty() {
            platforms.insert(Platform::current());
            return Ok(platforms.into_iter().collect());
        }
    }

    // Fresh lockfile (or no parseable keys) — populate common defaults + current.
    let mut platforms: BTreeSet<Platform> = Platform::common_platforms().into_iter().collect();
    platforms.insert(Platform::current());
    Ok(platforms.into_iter().collect())
}

/// Determine target platforms from an existing lockfile for explicit `mise lock` calls.
/// If the lockfile already has platform entries, only those are targeted.
/// Otherwise, falls back to all common platforms + current platform.
pub(crate) fn determine_existing_platforms(lockfile_path: &Path) -> Result<Vec<Platform>> {
    // If lockfile_platforms setting is configured, use it as the authoritative set
    if let Some(configured) = Settings::get().lockfile_platforms()? {
        let mut platforms: BTreeSet<Platform> = configured.into_iter().collect();
        platforms.insert(Platform::current());
        return Ok(platforms.into_iter().collect());
    }

    if let Ok(lockfile) = Lockfile::read(lockfile_path) {
        let existing_keys = lockfile.all_platform_keys();
        if !existing_keys.is_empty() {
            let mut platforms: BTreeSet<Platform> = BTreeSet::new();
            for platform_key in existing_keys {
                if let Ok(p) = Platform::parse(&platform_key)
                    && p.validate().is_ok()
                {
                    platforms.insert(p);
                }
            }
            if !platforms.is_empty() {
                return Ok(platforms.into_iter().collect());
            }
        }
    }
    // No lockfile, no platforms yet, or no valid platform keys — use common defaults
    let mut platforms: BTreeSet<Platform> = Platform::common_platforms().into_iter().collect();
    platforms.insert(Platform::current());
    Ok(platforms.into_iter().collect())
}

