    let mut requested_versions_by_lockfile: HashMap<PathBuf, HashMap<String, BTreeSet<String>>> =
        HashMap::new();
    for (source, tools) in tools_by_source_for_update(ts, new_versions) {
        let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, &source) else {
            continue;
        };
        let requested = requested_versions_by_lockfile
            .entry(lockfile_path)
            .or_default();
        for (short, versions) in tools {
            requested
                .entry(short)
                .or_default()
                .extend(versions.into_iter().map(|tv| tv.version));
        }
    }

    let empty_keys: BTreeSet<String> = BTreeSet::new();
    let mut candidate_versions_by_lockfile: HashMap<PathBuf, Vec<ToolVersion>> = HashMap::new();
    let mut seen_candidates: HashMap<PathBuf, HashSet<(String, String, String, ToolSource)>> =
        HashMap::new();
    for tv in ts
        .versions
        .values()
        .flat_map(|tvl| tvl.versions.iter())
        .chain(new_versions.iter())
    {
        let Ok(backend) = tv.request.backend() else {
            continue;
        };
        if !backend.supports_lockfile_url() {
            continue;
        }
        if let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, tv.request.source())
        {
            let candidate_key = (
                tv.ba().short.clone(),
                tv.version.clone(),
                tv.request.version().to_string(),
                tv.request.source().clone(),
            );
            if seen_candidates
                .entry(lockfile_path.clone())
                .or_default()
                .insert(candidate_key)
            {
                candidate_versions_by_lockfile
                    .entry(lockfile_path)
                    .or_default()
                    .push(tv.clone());
            }
        }
    }

    for (lockfile_path, versions) in candidate_versions_by_lockfile {
        // Only update existing lockfiles (consistent with update_lockfiles)
        if !lockfile_path.exists() {
            continue;
        }

        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;
        let mut lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        let existing_keys;
        let pre_install_keys = if deferred_retry_only {
            existing_keys = lockfile.all_platform_keys();
            &existing_keys
        } else {
            pre_install_platforms
                .get(&lockfile_path)
                .unwrap_or(&empty_keys)
        };
        let target_platforms = determine_target_platforms_from_lockfile(pre_install_keys)?;

        let versions: Vec<_> = versions
            .into_iter()
            .filter(|tv| {
                let needs_auto_lock = if deferred_retry_only {
                    tool_version_needs_deferred_provenance_retry(&lockfile, tv, &target_platforms)
                } else {
                    tool_version_needs_auto_lock(&lockfile, tv, &target_platforms)
                };
                needs_auto_lock.unwrap_or_else(|err| {
                    debug!(
                        "auto-lock candidate check failed for {}@{} in {}: {}",
                        tv.short(),
                        tv.version,
                        display_path(&lockfile_path),
                        err
                    );
                    false
                })
            })
            .collect();
        if versions.is_empty() {
            continue;
        }

        let semaphore = Arc::new(Semaphore::new(jobs));
        let mut jset: JoinSet<LockResolutionResult> = JoinSet::new();

        for tv in &versions {
            let ba = tv.ba().clone();
            let backend = crate::backend::get(&ba);

            for platform in &target_platforms {
                // Expand platform variants from the backend
                let variants = if let Some(ref backend) = backend {
                    backend.platform_variants(platform)
                } else {
                    vec![platform.clone()]
                };

                for variant in variants {
                    let platform_key = variant.to_key();
                    let target = PlatformTarget::new(variant.clone());

                    // Skip complete targets unless a prior provenance-bearing version
                    // means this target still needs authoritative verification.
                    if let Some(ref backend) = backend
                        && let Ok(options) = backend.resolve_lockfile_options(&tv.request, &target)
                        && let Some(tools) = lockfile.tools.get(&ba.short)
                        && !lockfile_target_needs_auto_lock(
                            tools,
                            &tv.version,
                            &platform_key,
                            &options,
                        )
                    {
                        continue;
                    }

                    let semaphore = semaphore.clone();
                    let ba = ba.clone();
                    let tv = (*tv).clone();
                    let backend = backend.clone();

                    jset.spawn(async move {
                        let _permit = semaphore.acquire().await;
                        resolve_tool_lock_info(ba, tv, variant, backend).await
                    });
                }
            }
        }

        // Collect results and update lockfile
        // Defer provenance errors until after saving so unaffected tools' entries aren't lost.
        let mut provenance_errors: Vec<String> = Vec::new();
        while let Some(result) = jset.join_next().await {
            match result {
                Ok(resolution) => {
                    if let Err(msg) = &resolution.4 {
                        let (short, version, backend, platform) =
                            (&resolution.0, &resolution.1, &resolution.2, &resolution.3);
                        let platform_key = platform.to_key();
                        // Auto-lock is best-effort, so resolution failures are normally
                        // just logged. But if this url-less version is a deferred
                        // provenance upgrade — a prior provenance-bearing version is
                        // still present as a baseline — a failure here means the
                        // deferred supply-chain check could not be completed. Fail
                        // closed rather than silently locking the upgrade without
                        // provenance (#11225); it self-heals on a later successful run.
                        if let Some(err) = deferred_provenance_resolution_error(
                            lockfile.tools.get(short).map(Vec::as_slice),
                            short,
                            version,
                            backend,
                            &platform_key,
                            msg,
                        ) {
                            provenance_errors.push(err);
                        } else {
                            debug!("auto-lock: {msg}");
                        }
                    }
                    if let Err(e) = apply_lock_result(&mut lockfile, resolution) {
                        provenance_errors.push(e.to_string());
                    }
                }
                Err(e) => {
                    debug!("auto-lock task failed: {}", e);
                }
            }
        }

        // Monorepo root lockfiles hold sibling projects' entries that this run cannot
        // see, so an absent version there is not necessarily a baseline. Fail closed
        // and leave them alone, as `update_lockfiles` does.
        let is_monorepo_root_lockfile = config
            .monorepo_lockfile_root()
            .is_some_and(|root| lockfile_path.parent() == Some(root.as_path()));
        if provenance_errors.is_empty() && !is_monorepo_root_lockfile {
            let current_platform = Platform::current().to_key();
            let empty = BTreeSet::new();
            let requested = requested_versions_by_lockfile.get(&lockfile_path);
            for (short, tools) in lockfile.tools.iter_mut() {
                let requested_versions = requested
                    .and_then(|requested| requested.get(short))
                    .unwrap_or(&empty);
                for version in prune_verified_provenance_baselines(
                    tools,
                    requested_versions,
                    &current_platform,
                ) {
                    debug!(
                        "auto-lock: pruned {short}@{version} from {}: provenance baseline no longer needed",
                        display_path(&lockfile_path)
                    );
                }
            }
        }

        lockfile.save(&lockfile_path)?;

        all_provenance_errors.extend(provenance_errors);
    }

    if !all_provenance_errors.is_empty() {
        return Err(eyre!("{}", all_provenance_errors.join("\n")));
    }

    Ok(())
}

fn deferred_provenance_resolution_error(
    existing_tools: Option<&[LockfileTool]>,
    short: &str,
    version: &str,
    backend: &str,
    platform_key: &str,
    resolution_error: &str,
) -> Option<String> {
    find_provenance_regression_baseline(existing_tools, version, backend, platform_key, None)?;
    Some(format!(
        "could not verify provenance for {short}@{version} on \
         {platform_key}: {resolution_error}\nA prior version had provenance, so \
         mise refuses to lock this upgrade without verifying it. \
         Retry once the release source is reachable."
    ))
}

/// Result type for lock resolution tasks (shared by `mise lock` and auto-lock).
///
/// Fields: (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// The `info_or_error` field is `Ok(info)` on success or `Err(message)` on failure,
/// allowing callers to log at the appropriate level. `error_is_fatal` distinguishes
/// genuine conda solve failures from backends that use errors to skip unsupported targets.
pub(crate) type LockResolutionResult = (
    String,
    String,
    String,
    Platform,
    Result<PlatformInfo, String>,
    BTreeMap<String, String>,
    BTreeMap<String, CondaPackageInfo>,
    BTreeMap<String, PkgxPackageInfo>,
    bool,
);

/// Resolve lock info for a single tool/platform combination.
///
/// Returns a tuple of (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// Does not log errors — callers decide the appropriate log level.
pub(crate) async fn resolve_tool_lock_info(
    ba: crate::cli::args::BackendArg,
    tv: ToolVersion,
    platform: Platform,
    backend: Option<crate::backend::ABackend>,
) -> LockResolutionResult {
    let target = PlatformTarget::new(platform.clone());
    let error_is_fatal = backend
        .as_ref()
        .is_some_and(|backend| backend.get_type() == BackendType::Conda);

    let (info, options, conda_packages, pkgx_packages) = if let Some(backend) = backend {
        let options = match backend.resolve_lockfile_options(&tv.request, &target) {
            Ok(options) => options,
            Err(e) => {
                return (
                    ba.short.clone(),
                    tv.version.clone(),
                    ba.stored_full(),
                    platform,
                    Err(e.to_string()),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    error_is_fatal,
                );
            }
        };
        match crate::env::with_install_env(
            tv.install_env(),
            backend.resolve_lock_info(&tv, &target),
        )
        .await
        {
            Ok(info) => {
                let conda_packages = if backend.get_type() == BackendType::Conda {
                    let conda_backend = CondaBackend::from_arg(ba.clone());
                    match conda_backend.resolve_conda_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve conda packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                let pkgx_packages = if backend.get_type() == BackendType::Pkgx {
                    let pkgx_backend = PkgxBackend::from_arg(ba.clone());
                    match pkgx_backend.resolve_pkgx_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve pkgx packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                (Ok(info), options, conda_packages, pkgx_packages)
            }
            Err(e) => (
                Err(format!(
                    "failed to resolve {} for {}: {}",
                    ba.short,
                    platform.to_key(),
                    e
                )),
                options,
                BTreeMap::new(),
                BTreeMap::new(),
            ),
        }
    } else {
        (
            Err(format!("backend not found for {}", ba.short)),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
        )
    };

    (
        ba.short.clone(),
        tv.version.clone(),
        ba.full(),
        platform,
        info,
        options,
        conda_packages,
        pkgx_packages,
        error_is_fatal,
    )
}

