                    .map(|tool| tool.version.as_str())
                    .collect::<Vec<_>>();
                if lost_versions.is_empty() {
                    return None;
                }
                Some(format!(
                    "failed to resolve {}@{} for {}; refusing to replace locked version(s) {} that support this platform",
                    result.short,
                    result.version,
                    result.platform,
                    lost_versions.join(", ")
                ))
            })
            .collect()
    }

