impl Toolset {
    async fn missing_lazy_bin_provider(
        &self,
        config: &Arc<Config>,
        bin_name: &str,
    ) -> Result<Option<ToolVersion>> {
        let mut providers = self
            .list_missing_versions_for_install(config)
            .await
            .into_iter()
            .filter_map(|tv| {
                let options = tv.request.options();
                if options.lazy == Some(true) {
                    match tv.request.lazy_bins() {
                        Ok(Some(bins))
                            if bins.iter().any(|bin| lazy_bin_names_eq(bin, bin_name)) =>
                        {
                            Some(Ok(tv))
                        }
                        Ok(_) => None,
                        // Missing metadata for one lazy declaration says nothing
                        // about whether another declaration provides this command.
                        // ensure_lazy_shims reports that declaration's error while
                        // still materializing the valid providers' shims.
                        Err(_) => None,
                    }
                } else if tv.ba().matches_bin_name(bin_name)
                    || tv
                        .ba()
                        .registry_tool()
                        .is_some_and(|tool| tool.provides_bin(bin_name))
                {
                    Some(Ok(tv))
                } else {
                    None
                }
            })
            .map(|tv| tv.and_then(|tv| Ok((tv.backend()?, tv))))
            .collect::<Result<Vec<_>>>()?;
        Self::sort_by_overrides(&mut providers)?;
        Ok(providers
            .into_iter()
            .next()
            .and_then(|(_, tv)| (tv.request.options().lazy == Some(true)).then_some(tv)))
    }

    pub(crate) async fn has_missing_lazy_bin_provider(
        &self,
        config: &Arc<Config>,
        bin_name: &str,
    ) -> Result<bool> {
        Ok(self
            .missing_lazy_bin_provider(config, bin_name)
            .await?
            .is_some())
    }

    /// A lazy tool's dependencies are commonly lazy themselves, so nothing else
    /// installs them and the provider alone fails its dependency preflight.
    async fn lazy_install_requests(
        &self,
        config: &Arc<Config>,
        tv: &ToolVersion,
    ) -> Vec<ToolRequest> {
        let missing = self.list_missing_versions_for_install(config).await;
        let mut requests = vec![tv.request.clone()];
        let mut next = 0;
        while next < requests.len() {
            let declarations = install_dependency_declarations(&requests[next]);
            next += 1;
            for candidate in &missing {
                // Keyed on the request, not the backend: the preflight requires every
                // configured version of a dependency, not just the first one.
                if declarations.matches(candidate.ba()) && !requests.contains(&candidate.request) {
                    requests.push(candidate.request.clone());
                }
            }
        }
        requests
    }

    pub(crate) async fn install_missing_lazy_bin(
        &mut self,
        config: &mut Arc<Config>,
        bin_name: &str,
    ) -> Result<Option<Vec<ToolVersion>>> {
        let Some(tv) = self.missing_lazy_bin_provider(config, bin_name).await? else {
            return Ok(None);
        };
        // The batch can span scopes, so each tool resolves its own destination rather
        // than inheriting the provider's. The provider's own directory is still needed
        // to explain a failure that is caused by writing outside the user's install dir.
        let provider_install_dir = scope_installs_dir(&tv.request);
        let install_options = InstallOptions {
            reason: "lazy shim".into(),
            scoped_install_dirs: true,
            ..Default::default()
        };
        let requests = self.lazy_install_requests(config, &tv).await;
        let installed = self
            .install_all_versions(config, requests, &install_options)
            .await
            .wrap_err_with(|| {
                provider_install_dir.as_ref().map_or_else(
                    || format!("failed to install lazy tool {}", tv.style()),
                    |dir| {
                        format!(
                            "failed to install lazy tool {} into {}. Preinstall it with appropriate privileges or set system_installs_dir to a writable directory",
                            tv.style(),
                            crate::file::display_path(dir)
                        )
                    },
                )
            })?;
        if !installed.is_empty() {
