//! Generate selected scope from requests with an immutable previous lockfile.
use super::*;
use crate::ui::multi_progress_report::MultiProgressReport;

pub(crate) type Tool = (crate::cli::args::BackendArg, ToolVersion);

pub(crate) async fn generate(
    previous: &Lockfile,
    tools: &[Tool],
    platforms: &[Platform],
    filtered_tools: bool,
    filtered_platforms: bool,
    jobs: usize,
) -> Result<Lockfile> {
    let mut candidate = Lockfile {
        lockfile_version: previous.lockfile_version,
        generated_header_url: previous.generated_header_url.clone(),
        ..Default::default()
    };
    let selected: BTreeSet<_> = tools.iter().map(|(ba, _)| ba.short.as_str()).collect();
    let mut targets = Vec::new();
    let mut keys = BTreeSet::new();
    for (ba, tv) in tools {
        let backend = tv.backend()?;
        for platform in platforms {
            for platform in backend.platform_variants(platform) {
                let options = backend.resolve_lockfile_options(&tv.request, &PlatformTarget::new(platform.clone()))?;
                keys.insert((ba.short.clone(), platform.to_key()));
                targets.push((ba.clone(), tv.clone(), platform, options));
            }
        }
    }
    for (short, entries) in &previous.tools {
        for entry in entries {
            let mut untouched = entry.clone();
            if selected.contains(short.as_str()) {
                if !filtered_platforms { continue; }
                untouched.platforms.retain(|platform, _| !keys.contains(&(short.clone(), platform.clone())));
                if untouched.platforms.is_empty() { continue; }
            } else if !filtered_tools { continue; }
            candidate.tools.entry(short.clone()).or_default().push(untouched);
        }
    }
    candidate.conda_packages = previous.conda_packages.clone();
    candidate.pkgx_packages = previous.pkgx_packages.clone();
    let report = MultiProgressReport::get().add("lock");
    report.set_length(targets.len() as u64);
    let semaphore = Arc::new(Semaphore::new(crate::jobs::normalize(jobs)));
    let mut tasks = JoinSet::new();
    for (ba, tv, platform, options) in targets {
        let previous_info = previous.tools.get(&ba.short).and_then(|entries| {
            entries.iter().find(|entry| {
                entry.version == tv.version && entry.options == options
                    && entry.backend.as_deref() == Some(ba.stored_full().as_str())
            }).and_then(|entry| entry.platforms.get(&platform.to_key())).cloned()
        });
        let semaphore = semaphore.clone();
        tasks.spawn(async move {
            let _permit = semaphore.acquire().await?;
            let backend = tv.backend()?;
            let mut resolution = if let Some(info) = previous_info.filter(|info| {
                info.checksum.is_some() && info.url.is_some() && !Settings::get().force_provenance_verify()
            }) {
                (ba.short.clone(), tv.version.clone(), ba.stored_full(), platform, Ok(info), options,
                 BTreeMap::new(), BTreeMap::new(), false)
            } else {
                resolve_tool_lock_info(ba, tv.clone(), platform, Some(backend)).await
            };
            if let Ok(info) = &mut resolution.4 {
                if info.checksum.is_none() && let Some(url) = &info.url {
                    let temp = tempfile::tempdir()?;
                    let path = temp.path().join("artifact");
                    crate::http::HTTP.download_file(url, &path, None).await?;
                    info.checksum = Some(format!("sha256:{}", crate::hash::file_hash_sha256(&path, None)?));
                }
            }
            Ok::<_, eyre::Report>((tv.request.version(), resolution))
        });
    }
    let mut completed = 0;
    while let Some(result) = tasks.join_next().await {
        let (specifier, resolution) = result??;
        completed += 1;
        report.set_position(completed);
        report.set_message(format!("{}@{} {}", resolution.0, resolution.1, resolution.3.to_key()));
        let (short, version, backend, platform, info, options, conda, pkgx, _) = resolution;
        let info = info.map_err(|error| eyre!(error))?;
        if let Some(error) = check_single_tool_provenance(
            previous.tools.get(&short).map(Vec::as_slice), &short, &version,
            &backend, &platform.to_key(), info.provenance.as_ref(),
        ) {
            report.abandon();
            bail!("{error}");
        }
        candidate.set_platform_info(&short, &version, Some(&backend), &options, &platform.to_key(), info);
        candidate.bind_request(&short, &specifier, &version, &options);
        for (key, value) in conda { candidate.set_conda_package(&platform.to_key(), &key, value); }
        for (key, value) in pkgx { candidate.set_pkgx_package(&platform.to_key(), &key, value); }
    }
    candidate.cleanup_unreferenced_conda_packages();
    candidate.cleanup_unreferenced_pkgx_packages();
    report.finish_with_message(format!("{completed} platform entries"));
    Ok(candidate)
}

