                                    Ok(tv) => {
                                        push_unique_lock_tool(
                                            &mut all_tools,
                                            (ba.as_ref().clone(), tv),
                                        );
                                    }
                                    Err(err) => {
                                        if active_unresolved {
                                            return Err(err.wrap_err(format!(
                                                "failed to resolve {request} for lockfile {}",
                                                display_path(target_lockfile_path)
                                            )));
                                        } else {
