    async fn verify_provenance_at_lock_time(
        &self,
        tv: &ToolVersion,
        opts: &GitBackendOptions<'_>,
        asset: &ReleaseAsset,
        target: &PlatformTarget,
        verification: AssetVerification,
    ) -> Result<Option<ProvenanceType>> {
