//MISE description="Render JSON schema"
//MISE depends=["docs:setup"]

import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as toml from "toml";

type EnumValue = string | boolean | number;
type EnumItem = EnumValue | { value: EnumValue; description?: string };

type Props = {
  type: string;
  description: string;
  default?: unknown;
  rust_type?: string;
  deprecated?: string;
  enum?: EnumItem[];
  rc?: boolean;
};

type SettingsNode = Props | { [key: string]: SettingsNode };
type SettingsToml = Record<string, SettingsNode>;
type JsonObject = Record<string, unknown>;

type Element = {
  type: string | string[];
  default: unknown;
  description: string;
  deprecated?: true;
  minimum?: number;
  enum?: EnumValue[];
  items?: {
    type: string | string[];
    enum?: EnumValue[];
  };
  additionalProperties?: {
    type: string;
  };
};

type NestedElement = {
  type: "object";
  unevaluatedProperties: false;
  deprecated?: true;
  properties: Record<string, Element | NestedElement>;
};

const writtenPaths: string[] = [];

function writeFormattedJson(path: string, value: unknown) {
  fs.writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
  writtenPaths.push(path);
}

function formatWithPrettier(paths: string[]) {
  if (paths.length === 0) return;
  const result = spawnSync("prettier", ["--write", ...paths], {
    stdio: "inherit",
  });
  if (result.error) {
    throw new Error(`prettier failed to spawn: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(`prettier exited with status ${result.status}`);
  }
}

function crawlReferencedDefs(schema: JsonObject, root: unknown) {
  const defs = schema["$defs"] as JsonObject | undefined;
  if (!defs) {
    throw new Error("schema/mise.json is missing $defs");
  }

  const queued = [root];
  const seenDefs = new Set<string>();
  const picked: JsonObject = {};

  for (let i = 0; i < queued.length; i++) {
    const value = queued[i];
    if (Array.isArray(value)) {
      queued.push(...value);
      continue;
    }
    if (!value || typeof value !== "object") {
      continue;
    }

    const obj = value as JsonObject;

